INSERT INTO subscriber_site_preferences (subscriber_id, site_type)
SELECT subscriber_id, 'TAKLIT_TAGSIS'
FROM subscriber_site_preferences
WHERE site_type = 'KOSGEB'
ON CONFLICT DO NOTHING;

INSERT INTO department_sites (department_id, site_type)
SELECT department_id, 'TAKLIT_TAGSIS'
FROM department_sites
WHERE site_type = 'KOSGEB'
ON CONFLICT DO NOTHING;

DELETE FROM announcements WHERE source_site = 'KOSGEB';
DELETE FROM subscriber_site_preferences WHERE site_type = 'KOSGEB';
DELETE FROM department_sites WHERE site_type = 'KOSGEB';
